create or replace function public.web_upsert_customer(p_store uuid, p_phone text, p_name text default null, p_email text default null, p_marketing_opt_in boolean default false) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_phone text := regexp_replace(coalesce(p_phone, ''), '\D', '', 'g'); v_cust public.customers; begin perform public.assert_service(); if p_store is null or v_phone = '' then raise exception 'store_and_phone_required' using errcode = '22023'; end if; perform set_config('floor.store_id', p_store::text, true); insert into public.customers (store_id, phone, name, email, marketing_opt_in, signup_code) values (p_store, v_phone, nullif(btrim(coalesce(p_name, '')), ''), nullif(btrim(coalesce(p_email, '')), ''), coalesce(p_marketing_opt_in, false), public.new_signup_code()) on conflict (store_id, phone) do update set name = coalesce(excluded.name, public.customers.name), email = coalesce(excluded.email, public.customers.email), marketing_opt_in = public.customers.marketing_opt_in or excluded.marketing_opt_in returning * into v_cust; return public.customer_card(p_store, v_cust) || jsonb_build_object('first_purchase_discount_used', v_cust.first_purchase_discount_used, 'points_balance', public.customer_points_balance_internal(p_store, v_cust.id)); end; $$;
create or replace function public.web_lookup_customer(p_store uuid, p_phone text) returns jsonb language plpgsql stable security definer set search_path = public as $$ declare v_phone text := regexp_replace(coalesce(p_phone, ''), '\D', '', 'g'); r public.customers; begin perform public.assert_service(); if p_store is null or v_phone = '' then raise exception 'store_and_phone_required' using errcode = '22023'; end if; select * into r from public.customers where store_id = p_store and phone = v_phone; if not found then return null; end if; return public.customer_card(p_store, r); end; $$;
create or replace function public.unsubscribe_loyalty(p_token uuid) returns jsonb language plpgsql security definer set search_path = public as $$ declare r public.customers; begin if p_token is null then raise exception 'token_required' using errcode = '22023'; end if; update public.customers set unsubscribed_at = coalesce(unsubscribed_at, now()), marketing_opt_in = false where unsub_token = p_token returning * into r; if not found then raise exception 'unknown_token' using errcode = 'P0001'; end if; return jsonb_build_object('ok', true, 'email', r.email); end; $$;
drop function if exists public.web_upsert_customer(uuid, text, text, text);;
